
from pathlib import Path
import json
import os
import re
import sqlite3
from datetime import datetime, timezone

import joblib
import pandas as pd
from flask import Flask, jsonify, request, session, send_from_directory
from werkzeug.security import generate_password_hash, check_password_hash


# --------------------------------------------------
# 1. CONFIGURATION
# --------------------------------------------------

BASE_DIR = Path(__file__).resolve().parent
FRONTEND_DIR = BASE_DIR.parent / "frontend"

DB_PATH = BASE_DIR / "somnia.db"

# Match the paths generated by train_model.py.
MODEL_PATH = BASE_DIR / "models" / "sleep_disorder_pipeline.joblib"
METRICS_PATH = BASE_DIR / "models" / "model_metrics.json"

TARGET_COLUMN = "Sleep Disorder"

NUMERIC_FIELDS = {
    "Age",
    "Sleep Duration",
    "Quality of Sleep",
    "Physical Activity Level",
    "Stress Level",
    "Heart Rate",
    "Daily Steps",
    "Systolic BP",
    "Diastolic BP",
}

app = Flask(__name__, static_folder=None)

app.config.update(
    SECRET_KEY=os.environ.get(
        "SECRET_KEY",
        "dev-only-change-this-before-deployment"
    ),
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=(
        os.environ.get("SESSION_COOKIE_SECURE", "0") == "1"
    ),
    MAX_CONTENT_LENGTH=32 * 1024,
)


# --------------------------------------------------
# 2. DATABASE
# --------------------------------------------------

def connect_db():
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA foreign_keys = ON")
    return con


def init_db():
    with connect_db() as con:
        con.execute("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
        """)

        con.execute("""
            CREATE TABLE IF NOT EXISTS assessments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                input_json TEXT NOT NULL,
                predicted_class TEXT NOT NULL,
                model_version TEXT NOT NULL,
                FOREIGN KEY(user_id)
                    REFERENCES users(id) ON DELETE CASCADE
            )
        """)


init_db()


# --------------------------------------------------
# 3. AUTHENTICATION HELPERS
# --------------------------------------------------

def current_user():
    uid = session.get("user_id")

    if not uid:
        return None

    with connect_db() as con:
        return con.execute(
            "SELECT id, name, email FROM users WHERE id = ?",
            (uid,)
        ).fetchone()


def require_user():
    user = current_user()

    if not user:
        return None, (
            jsonify({"error": "Please log in to continue."}),
            401
        )

    return user, None


# --------------------------------------------------
# 4. MODEL LOADING
# --------------------------------------------------

def load_model():
    """
    Load the complete sklearn Pipeline saved by train_model.py.

    The artifact is a Pipeline itself, not a dictionary
    containing a separate 'pipeline' key.
    """

    if not MODEL_PATH.is_file():
        app.logger.error("Model artifact not found: %s", MODEL_PATH)
        return None

    try:
        model = joblib.load(MODEL_PATH)

        if not hasattr(model, "predict"):
            app.logger.error("Loaded artifact has no predict method.")
            return None

        if not hasattr(model, "feature_names_in_"):
            app.logger.error("Model has no recorded feature schema.")
            return None

        return model

    except Exception:
        app.logger.exception("Could not load model artifact")
        return None


def get_feature_columns(model):
    """Return feature names in the exact order used during training."""
    return list(model.feature_names_in_)


# --------------------------------------------------
# 5. INPUT VALIDATION AND FEATURE PREPARATION
# --------------------------------------------------

def prepare_assessment(body, feature_columns):
    """
    Validate form input and create the feature row expected
    by the trained model.

    Supports either:
      - Systolic BP and Diastolic BP separately, or
      - Blood Pressure in a format such as 126/83.
    """

    if not isinstance(body, dict):
        raise ValueError("Please submit assessment data as a JSON object.")

    values = {}

    # Support a single Blood Pressure field from the frontend.
    blood_pressure = body.get("Blood Pressure")

    if blood_pressure is not None:
        match = re.fullmatch(
            r"\s*(\d{2,3})\s*/\s*(\d{2,3})\s*",
            str(blood_pressure)
        )

        if not match:
            raise ValueError(
                "Blood pressure must use the format systolic/diastolic, "
                "for example 126/83."
            )

        if body.get("Systolic BP") in (None, ""):
            body = {
                **body,
                "Systolic BP": match.group(1)
            }

        if body.get("Diastolic BP") in (None, ""):
            body = {
                **body,
                "Diastolic BP": match.group(2)
            }

    # Require every feature used by the trained model.
    for column in feature_columns:
        value = body.get(column)

        if value is None or str(value).strip() == "":
            raise ValueError(
                f"Please complete the required field: {column}."
            )

        if isinstance(value, (dict, list, bool)):
            raise ValueError(f"Invalid value for {column}.")

        if column in NUMERIC_FIELDS:
            try:
                number = float(value)
            except (TypeError, ValueError):
                raise ValueError(f"{column} must be a number.")

            if not pd.notna(number):
                raise ValueError(f"{column} must be a finite number.")

            import math
            if not math.isfinite(number):
                raise ValueError(f"{column} must be a finite number.")

            values[column] = number

        else:
            values[column] = str(value).strip()

    # Basic range validation.
    ranges = {
        "Age": (1, 120),
        "Sleep Duration": (0, 24),
        "Quality of Sleep": (1, 10),
        "Stress Level": (1, 10),
        "Physical Activity Level": (0, 1440),
        "Heart Rate": (20, 250),
        "Daily Steps": (0, 200000),
        "Systolic BP": (50, 300),
        "Diastolic BP": (30, 200),
    }

    for column, (minimum, maximum) in ranges.items():
        if column not in values:
            continue

        number = values[column]

        if not minimum <= number <= maximum:
            raise ValueError(
                f"{column} must be between {minimum} and {maximum}."
            )

    # These fields represent counts or whole-number scores.
    integer_fields = {
        "Age",
        "Quality of Sleep",
        "Stress Level",
        "Physical Activity Level",
        "Heart Rate",
        "Daily Steps",
        "Systolic BP",
        "Diastolic BP",
    }

    for column in integer_fields:
        if column in values and not values[column].is_integer():
            raise ValueError(f"{column} must be a whole number.")

    return values


# --------------------------------------------------
# 6. GENERAL SLEEP-HYGIENE SUGGESTIONS
# --------------------------------------------------

def suggestions_for(data):
    tips = []

    sleep_hours = data.get("Sleep Duration")
    stress = data.get("Stress Level")
    activity = data.get("Physical Activity Level")

    if isinstance(sleep_hours, (int, float)) and sleep_hours < 7:
        tips.append(
            "Consider reviewing your sleep schedule and allowing "
            "adequate time for rest."
        )

    if isinstance(stress, (int, float)) and stress >= 7:
        tips.append(
            "A calming wind-down routine or relaxation practice "
            "may be worth exploring."
        )

    if isinstance(activity, (int, float)) and activity < 30:
        tips.append(
            "If appropriate for you, consider regular daytime movement."
        )

    tips.append(
        "Try keeping sleep and wake times consistent across the week."
    )

    tips.append(
        "These are general sleep-hygiene ideas, not treatment "
        "or a promise of improved health."
    )

    return tips


# --------------------------------------------------
# 7. ASSESSMENT SERIALIZATION
# --------------------------------------------------

def safe_assessment(row):
    return {
        "id": row["id"],
        "created_at": row["created_at"],
        "predicted_class": row["predicted_class"],
        "model_version": row["model_version"],
        "inputs": json.loads(row["input_json"]),
    }


# --------------------------------------------------
# 8. FRONTEND ROUTES
# --------------------------------------------------

@app.get("/")
def home():
    if not (FRONTEND_DIR / "index.html").is_file():
        return jsonify({"error": "Frontend index.html was not found."}), 404

    return send_from_directory(FRONTEND_DIR, "index.html")


@app.get("/<path:path>")
def frontend_files(path):
    candidate = (FRONTEND_DIR / path).resolve()
    frontend_root = FRONTEND_DIR.resolve()

    if (
        frontend_root not in candidate.parents
        or not candidate.is_file()
    ):
        return jsonify({"error": "Not found"}), 404

    return send_from_directory(FRONTEND_DIR, path)


# --------------------------------------------------
# 9. CURRENT USER
# --------------------------------------------------

@app.get("/api/me")
def me():
    user = current_user()

    if not user:
        return jsonify({"user": None})

    return jsonify({
        "user": {
            "id": user["id"],
            "name": user["name"],
            "email": user["email"],
        }
    })


# --------------------------------------------------
# 10. REGISTER
# --------------------------------------------------

@app.post("/api/register")
def register():
    body = request.get_json(silent=True) or {}

    name = str(body.get("name", "")).strip()
    email = str(body.get("email", "")).strip().lower()
    password = str(body.get("password", ""))

    if (
        not name
        or len(name) > 80
        or not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email)
        or len(email) > 254
        or len(password) < 8
    ):
        return jsonify({
            "error": (
                "Enter a name, valid email, and password "
                "with at least 8 characters."
            )
        }), 400

    try:
        with connect_db() as con:
            cur = con.execute(
                """
                INSERT INTO users
                    (name, email, password_hash, created_at)
                VALUES (?, ?, ?, ?)
                """,
                (
                    name,
                    email,
                    generate_password_hash(password),
                    datetime.now(timezone.utc).isoformat(),
                ),
            )
            uid = cur.lastrowid

        session.clear()
        session["user_id"] = uid

        return jsonify({
            "message": "Account created.",
            "user": {
                "id": uid,
                "name": name,
                "email": email,
            },
        }), 201

    except sqlite3.IntegrityError:
        return jsonify({
            "error": "An account with that email already exists."
        }), 409


# --------------------------------------------------
# 11. LOGIN
# --------------------------------------------------

@app.post("/api/login")
def login():
    body = request.get_json(silent=True) or {}

    email = str(body.get("email", "")).strip().lower()
    password = str(body.get("password", ""))

    with connect_db() as con:
        user = con.execute(
            "SELECT * FROM users WHERE email = ?",
            (email,),
        ).fetchone()

    if not user or not check_password_hash(
        user["password_hash"], password
    ):
        return jsonify({
            "error": "Email or password is incorrect."
        }), 401

    session.clear()
    session["user_id"] = user["id"]

    return jsonify({
        "message": "Logged in.",
        "user": {
            "id": user["id"],
            "name": user["name"],
            "email": user["email"],
        },
    })


# --------------------------------------------------
# 12. LOGOUT
# --------------------------------------------------

@app.post("/api/logout")
def logout():
    session.clear()
    return jsonify({"message": "Logged out."})


# --------------------------------------------------
# 13. DASHBOARD
# --------------------------------------------------

@app.get("/api/dashboard")
def dashboard():
    user, error = require_user()

    if error:
        return error

    with connect_db() as con:
        rows = con.execute(
            """
            SELECT *
            FROM assessments
            WHERE user_id = ?
            ORDER BY id DESC
            LIMIT 20
            """,
            (user["id"],),
        ).fetchall()

    return jsonify({
        "user": {
            "name": user["name"],
            "email": user["email"],
        },
        "assessments": [
            safe_assessment(row) for row in rows
        ],
        "model_ready": MODEL_PATH.is_file(),
    })


# --------------------------------------------------
# 14. MODEL METRICS
# --------------------------------------------------

@app.get("/api/metrics")
def metrics():
    if not METRICS_PATH.is_file():
        return jsonify({
            "available": False,
            "message": "Train the model to see evaluation metrics.",
        })

    try:
        data = json.loads(
            METRICS_PATH.read_text(encoding="utf-8")
        )

        return jsonify({
            "available": True,
            "accuracy": data.get("accuracy"),
            "accuracy_percent": data.get("accuracy_percent"),
            "macro_f1": data.get("macro_f1"),
            "weighted_f1": data.get("weighted_f1"),
            "classes": data.get("classes", []),
            "test_rows": data.get(
                "testing_rows",
                data.get("test_rows")
            ),
            "note": (
                "Evaluation on the held-out test set; "
                "not a guarantee of real-world accuracy."
            ),
        })

    except (OSError, json.JSONDecodeError):
        app.logger.exception("Could not read model metrics")

        return jsonify({
            "available": False,
            "message": "Metrics file could not be read.",
        })


# --------------------------------------------------
# 15. SLEEP DISORDER ASSESSMENT
# --------------------------------------------------

@app.post("/api/assess")
def assess():
    user, error = require_user()

    if error:
        return error

    body = request.get_json(silent=True)

    if not isinstance(body, dict):
        return jsonify({
            "error": "Please submit a valid JSON assessment."
        }), 400

    model = load_model()

    if model is None:
        return jsonify({
            "error": (
                "The ML model is not ready. Run "
                "'python train_model.py' in the backend folder."
            )
        }), 503

    try:
        feature_columns = get_feature_columns(model)
        values = prepare_assessment(body, feature_columns)

        # Preserve the exact feature names and order used in training.
        X = pd.DataFrame(
            [values],
            columns=feature_columns,
        )

        prediction = str(model.predict(X)[0])

    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400

    except Exception:
        app.logger.exception("Prediction failed")

        return jsonify({
            "error": (
                "The model could not process these values. "
                "Check that the form fields match the trained dataset."
            )
        }), 422

    now = datetime.now(timezone.utc).isoformat()
    version = "sleep-disorder-rf-v1"

    try:
        with connect_db() as con:
            cur = con.execute(
                """
                INSERT INTO assessments
                    (
                        user_id,
                        created_at,
                        input_json,
                        predicted_class,
                        model_version
                    )
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    user["id"],
                    now,
                    json.dumps(values),
                    prediction,
                    version,
                ),
            )

            assessment_id = cur.lastrowid

        return jsonify({
            "id": assessment_id,
            "created_at": now,
            "predicted_class": prediction,
            "model_version": version,
            "suggestions": suggestions_for(values),
            "disclaimer": (
                "This is a dataset-based model estimate, "
                "not a medical diagnosis."
            ),
        }), 201

    except sqlite3.Error:
        app.logger.exception("Assessment save failed")

        return jsonify({
            "error": (
                "Prediction completed, but the result could not "
                "be saved. Please try again."
            )
        }), 500


# --------------------------------------------------
# 16. ASSESSMENT DETAILS
# --------------------------------------------------

@app.get("/api/assessments/<int:assessment_id>")
def assessment_detail(assessment_id):
    user, error = require_user()

    if error:
        return error

    with connect_db() as con:
        row = con.execute(
            """
            SELECT *
            FROM assessments
            WHERE id = ? AND user_id = ?
            """,
            (assessment_id, user["id"]),
        ).fetchone()

    if not row:
        return jsonify({"error": "Assessment not found."}), 404

    return jsonify(safe_assessment(row))


# --------------------------------------------------
# 17. DELETE ASSESSMENT
# --------------------------------------------------

@app.delete("/api/assessments/<int:assessment_id>")
def delete_assessment(assessment_id):
    user, error = require_user()

    if error:
        return error

    with connect_db() as con:
        cur = con.execute(
            """
            DELETE FROM assessments
            WHERE id = ? AND user_id = ?
            """,
            (assessment_id, user["id"]),
        )

    if cur.rowcount == 0:
        return jsonify({"error": "Assessment not found."}), 404

    return jsonify({"message": "Assessment deleted."})


